"use client";

/**
 * PerplexityExplorer — precomputed t-SNE embeddings of one labeled dataset
 * (300 points: three 10-D Gaussian classes plus one high-variance noise
 * dimension) at perplexity 2, 5, 30, 100, plus the PCA projection. A
 * selector tweens points between views (identity preserved, 180ms) with
 * points colored by class; the readout names the artifact at each extreme
 * (shattered micro-clusters at 2, merged blob at 100). Guided task
 * (lesson): find the perplexity where class structure is clearest, check
 * both extreme artifacts, compare the winner against PCA.
 * Data precomputed offline (numpy t-SNE, seed-fixed); each view is packed
 * as 2-digit (x, y) pairs on a 0-99 grid, class = floor(index / 100).
 */
import { useState } from "react";
import { Panel, PresetGroup, Readout } from "@/components/ui";

const P2 = "";
const P5 = "";
const P30 = "";
const P100 = "";
const PCA = "";

const W = 340, PAD = 14, SPAN = W - 2 * PAD;
const COLORS = ["#e2903a", "#4c8dd6", "#5aa46a"];
const CLASS_NAMES = ["class A", "class B", "class C"];

function decodeView(s: string): [number, number][] {
  const pts: [number, number][] = [];
  for (let i = 0; i < s.length; i += 4) {
    pts.push([
      PAD + (Number(s.slice(i, i + 2)) / 99) * SPAN,
      PAD + (Number(s.slice(i + 2, i + 4)) / 99) * SPAN,
    ]);
  }
  return pts;
}

const VIEWS = [
  {
    label: "perplexity 2",
    note: "Artifact — shattering: with ~2 effective neighbors per point, every class splits into disconnected micro-clusters.",
    pts: decodeView(P2),
  },
  {
    label: "perplexity 5",
    note: "Partial fragments: islands begin to gather, but split-off satellites of each class remain.",
    pts: decodeView(P5),
  },
  {
    label: "perplexity 30",
    note: "Three separated islands, one per class, with real gaps between them.",
    pts: decodeView(P30),
  },
  {
    label: "perplexity 100",
    note: "Artifact — merging: perplexity is a third of the dataset, the gaps close, and distinct classes share one blob.",
    pts: decodeView(P100),
  },
  {
    label: "PCA",
    note: "Linear projection onto the top-2 variance directions: the high-variance noise dimension dominates, and classes overlap.",
    pts: decodeView(PCA),
  },
];

export default function PerplexityExplorer() {
  // D3: open on perplexity 2 — the shattering artifact is visible immediately,
  // and the guided task (find the clearest perplexity) stays open.
  const [view, setView] = useState(0);
  const { label, note, pts } = VIEWS[view];

  return (
    <Panel>
      <PresetGroup
        labels={VIEWS.map((v) => v.label)}
        activeIndex={view}
        onSelect={setView}
      />
      <Readout>
        <strong>{label}</strong> — {note}
      </Readout>
      <div className="flex flex-wrap gap-x-4 gap-y-1 pt-2 text-xs">
        {CLASS_NAMES.map((name, c) => (
          <span key={name} className="inline-flex items-center gap-1.5">
            <span
              className="inline-block h-2.5 w-2.5 rounded-full"
              style={{ backgroundColor: COLORS[c] }}
            />
            {name}
          </span>
        ))}
        <span className="opacity-65">
          300 points · three 10-D Gaussian classes + one noise dimension
        </span>
      </div>
      <svg
        viewBox={`0 0 ${W} ${W}`}
        className="mx-auto mt-2 block w-full max-w-90"
        role="img"
        aria-label={`Two-dimensional map of the dataset under ${label}. ${note}`}
      >
        <rect x="0" y="0" width={W} height={W} rx="4" fill="currentColor" opacity="0.04" />
        {pts.map(([x, y], i) => (
          <circle
            key={i}
            cx="0"
            cy="0"
            r="3.2"
            fill={COLORS[Math.floor(i / 100)]}
            fillOpacity="0.85"
            style={{
              transform: `translate(${x}px, ${y}px)`,
              transition: "transform 180ms ease",
            }}
          />
        ))}
        <text x="8" y={W - 8} fontSize="10" fill="currentColor" opacity="0.65">
          same 300 points in every view — axes carry no meaning
        </text>
      </svg>
    </Panel>
  );
}
